  grid-row-gap: 1.25rem;
  background-color: #edf2fa;
  border-radius: 1.25rem;
  flex-flow: column;
  justify-content: flex-start;
  align-items: flex-start;
  padding: 2.5rem;
  display: flex;
}

.icon {
  width: 2.875rem;
}

.community_page {
  justify-content: center;
  align-items: flex-end;
  height: 20rem;
  display: flex;
}

.space_bottom {
  margin-bottom: 1rem;
}

.globe_section {
